<script setup lang="ts">import{ref}from'vue';import{History,Search}from'@lucide/vue';import{api}from'../services/api';const instrumentID=ref('');const trace=ref<unknown>();const error=ref('');async function load(){error.value='';try{trace.value=await api.trace(instrumentID.value)}catch(reason){error.value=reason instanceof Error?reason.message:'查询失败'}}</script><template><section><div class="page-title"><div><h1>追溯历史</h1><p>串联仪器状态、校准版本、使用记录与审计事件</p></div></div><div class="trace-search"><input v-model="instrumentID" placeholder="输入仪器 ID"><button class="primary" @click="load"><Search :size="17"/>查询追溯链</button></div><div v-if="error" class="notice error">{{error}}</div><pre v-if="trace" class="trace-output">{{JSON.stringify(trace,null,2)}}</pre><div v-else class="empty-state"><History :size="42"/><h2>等待查询</h2><p>输入仪器 ID 后可查看不可变审计与使用前校验记录。</p></div></section></template>

